/**
 * useSnapshot.js
 *
 * Custom hook that loads pipeline-data.json (generated by `npm run snapshot`).
 * Falls back to mock data if the file hasn't been generated yet.
 */

import { useState, useEffect } from 'react'
import { MOCK_SNAPSHOT } from './mock.js'

export function useSnapshot() {
  const [snapshot, setSnapshot] = useState(null)
  const [loading, setLoading]   = useState(true)
  const [error, setError]       = useState(null)

  useEffect(() => {
    let cancelled = false

    async function load() {
      try {
        const res = await fetch('./pipeline-data.json', { cache: 'no-cache' })
        if (!res.ok) throw new Error(`HTTP ${res.status}`)
        const data = await res.json()
        if (!cancelled) {
          setSnapshot({ ...data, is_live: data.is_live ?? true })
          setLoading(false)
        }
      } catch {
        // pipeline-data.json not found — use mock
        if (!cancelled) {
          setSnapshot(MOCK_SNAPSHOT)
          setLoading(false)
          setError('pipeline-data.json not found — showing mock data. Run: npm run snapshot')
        }
      }
    }

    load()
    return () => { cancelled = true }
  }, [])

  return { snapshot, loading, error }
}
